<?php
require_once __DIR__.'/includes/config.php'; require_login(); require_permission('sales'); $uid=(int)$_SESSION['user_id'];
$id=filter_var($_GET['id']??null,FILTER_VALIDATE_INT); if(!$id){http_response_code(404);exit('Receipt not found.');}
$q=$pdo->prepare('SELECT s.*,c.name customer,c.phone customer_phone,u.business_name,u.full_name FROM sales s JOIN users u ON u.id=s.user_id LEFT JOIN customers c ON c.id=s.customer_id WHERE s.id=? AND s.user_id=?');$q->execute([$id,$uid]);$sale=$q->fetch();if(!$sale){http_response_code(404);exit('Receipt not found.');}
$q=$pdo->prepare('SELECT product_name,quantity,unit_price,unit_cost FROM sale_items WHERE sale_id=? ORDER BY id');$q->execute([$id]);$items=$q->fetchAll();$balance=max(0,(float)$sale['total']-(float)$sale['amount_paid']);$pageTitle='Receipt #'.$id;require __DIR__.'/includes/header.php';?>
<div class="d-flex justify-content-between align-items-center flex-wrap gap-2 mb-3 no-print"><a class="btn btn-outline-secondary" href="sales.php">← Back to sales</a><button class="btn btn-primary" onclick="window.print()">Print receipt</button></div>
<div class="card receipt-card mx-auto" style="max-width:780px"><div class="card-body p-4 p-md-5"><div class="d-flex justify-content-between flex-wrap gap-3 border-bottom pb-4 mb-4"><div><div class="brand-mark d-inline-flex mb-2">K</div><h1 class="h3 fw-bold mb-1"><?=e($sale['business_name'])?></h1><div class="text-secondary">Sales receipt</div></div><div class="text-md-end"><div class="text-secondary small">RECEIPT NUMBER</div><div class="h4 fw-bold">#<?=str_pad((string)$id,6,'0',STR_PAD_LEFT)?></div><div><?=date('d M Y, H:i',strtotime($sale['created_at']))?></div></div></div>
<div class="row g-3 mb-4"><div class="col-sm-6"><div class="text-secondary small">CUSTOMER</div><div class="fw-semibold"><?=e($sale['customer']?:'Walk-in customer')?></div><?php if(!empty($sale['customer_phone'])):?><div><?=e($sale['customer_phone'])?></div><?php endif;?></div><div class="col-sm-6 text-sm-end"><div class="text-secondary small">PAYMENT METHOD</div><div class="fw-semibold"><?=e(ucfirst($sale['payment_method']))?></div><div class="text-secondary small mt-2">Recorded by <?=e($sale['full_name'])?></div></div></div>
<div class="table-responsive"><table class="table"><thead><tr><th>Item</th><th class="text-end">Qty</th><th class="text-end">Unit price</th><th class="text-end">Amount</th></tr></thead><tbody><?php foreach($items as $it):?><tr><td><?=e($it['product_name'])?></td><td class="text-end"><?=(int)$it['quantity']?></td><td class="text-end"><?=money($it['unit_price'])?></td><td class="text-end"><?=money((float)$it['unit_price']*(int)$it['quantity'])?></td></tr><?php endforeach;?></tbody></table></div>
<div class="row justify-content-end"><div class="col-sm-7 col-md-6"><div class="d-flex justify-content-between py-2"><span>Subtotal</span><span><?=money($sale['total'])?></span></div><div class="d-flex justify-content-between py-2"><span>Amount paid</span><strong><?=money($sale['amount_paid'])?></strong></div><div class="d-flex justify-content-between border-top pt-3 mt-1"><span class="fw-bold">Balance due</span><strong class="<?= $balance>0?'text-danger':'text-success' ?>"><?=money($balance)?></strong></div></div></div>
<?php if($sale['notes']):?><div class="alert alert-light border mt-4 mb-0"><strong>Note:</strong> <?=e($sale['notes'])?></div><?php endif;?><div class="text-center text-secondary small mt-5">Thank you for your patronage.</div></div></div>
<style>@media print{body{background:#fff!important}.app-nav,footer,.no-print{display:none!important}main.container{max-width:100%;padding:0!important}.receipt-card{border:0!important;box-shadow:none!important}.receipt-card .card-body{padding:0!important}}</style>
